{
  "cypher": "CALL {
  MATCH (m:Movie)-[:producedIn]->(c:Country),
        (m)-[:releasedIn]->(c)
  WHERE m.globalBoxOffice IS NOT NULL OR m.worldwideGross IS NOT NULL OR m.boxOffice IS NOT NULL
  WITH m, coalesce(m.globalBoxOffice, m.worldwideGross, m.boxOffice) AS boxOffice
  ORDER BY boxOffice ASC
  LIMIT 1
  RETURN m.name AS movieName
}
RETURN coalesce(movieName, 'No global box office data available in this graph, so the requested answer cannot be derived.') AS result;"
  ,"rationale":"Uses a single Country node linked via both producedIn and releasedIn relationships, retains coalesce ordering, and includes fallback message."
}

